from copy import deepcopy
import math


def _number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be a number")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")


def advance_profiles(profiles, target, keep_history=False):
    if not isinstance(profiles, list):
        raise TypeError("profiles must be a list")
    _number(target, "target")
    if type(keep_history) is not bool:
        raise TypeError("keep_history must be a bool")

    seen = set()
    result = []
    for source in profiles:
        if not isinstance(source, dict):
            raise TypeError("each profile must be a dictionary")
        if set(source) != {"id", "score", "adjustments", "metadata"}:
            raise ValueError("profile has incorrect keys")
        if not isinstance(source["id"], str):
            raise TypeError("id must be a string")
        if source["id"] in seen:
            raise ValueError("ids must be unique")
        seen.add(source["id"])
        _number(source["score"], "score")
        if not isinstance(source["adjustments"], list):
            raise TypeError("adjustments must be a list")
        for adjustment in source["adjustments"]:
            _number(adjustment, "adjustment")
        if not isinstance(source["metadata"], dict):
            raise TypeError("metadata must be a dictionary")

        profile = source.copy()
        history = [profile["score"]]
        while profile["score"] < target:
            candidates = [
                (value, -index, index)
                for index, value in enumerate(profile["adjustments"])
                if value > 0
            ]
            if not candidates:
                break
            _, _, index = max(candidates)
            adjustment = profile["adjustments"].pop(index)
            profile["score"] += adjustment
            history.append(profile["score"])
        if keep_history:
            profile["history"] = history
        result.append(profile)
    return result

